// Think of career goals as a phased progression
// Phase 1: Foundation (Years 0-2)
record TechnicalFoundation(
    String coreSkill,        // Java, Spring Boot, SQL
    String deliveryFocus,    // Building features, fixing bugs
    String learningGoal      // Understanding production systems
) {}

// Phase 2: Depth (Years 2-4)
record TechnicalDepth(
    String specialization,   // Microservices, performance tuning
    String ownershipLevel,   // Owning complete modules
    String mentoringRole     // Guiding junior developers
) {}

// Phase 3: Breadth (Years 4-6)
record TechnicalLeadership(
    String architecturalWork, // System design, tech decisions
    String crossTeamImpact,   // Influencing beyond your team
    String flexiblePath       // Tech lead or senior IC or manager
) {}

// Your answer should show you understand this progression
var careerPath = List.of(
    new TechnicalFoundation("Java backend", "shipping reliable code", "learning from senior devs"),
    new TechnicalDepth("distributed systems", "end-to-end feature ownership", "code reviews and mentoring"),
    new TechnicalLeadership("service architecture", "cross-team technical initiatives", "where I add most value")
);
```

