interface ProductRepository extends JpaRepository<Product, Long> {
    @Modifying
    @Query("update Product p set p.stock = p.stock - :quantity " +
           "where p.id = :id and p.stock >= :quantity")
    int reserveStock(Long id, int quantity);
}

@Transactional
void reserve(Long productId, int quantity) {
    if (quantity <= 0) throw new IllegalArgumentException("quantity");
    if (products.reserveStock(productId, quantity) != 1) {
        throw new InsufficientStockException(productId, quantity);
    }
}

// The database checks and updates stock in one statement.
// A cache must be updated or invalidated after a successful reservation.

