// Week 1: Manager assigns a well-scoped starter task
@Service
public class OrderService {
    // Clear requirement: "Add validation before saving orders"
    public Order createOrder(OrderRequest request) {
        // You write this, manager reviews and explains why certain checks matter
        if (request.items().isEmpty()) {
            throw new ValidationException("Order must have at least one item");
        }
        if (request.totalAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new ValidationException("Order total must be positive");
        }
        return orderRepository.save(request.toEntity());
    }
}

// Week 4: Manager gives you more autonomy
@RestController
public class OrderController {
    // Now you design the endpoint structure yourself
    // Manager reviews for REST best practices but doesn't dictate every detail
    @PostMapping("/api/orders")
    public ResponseEntity<OrderResponse> createOrder(@RequestBody OrderRequest request) {
        var order = orderService.createOrder(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(OrderResponse.from(order));
    }
}
